WITH cleaned AS (SELECT *, LAST_DAY(start_date) AS start_date_month_end, DAY(end_date) AS end_date_day FROM subscriptions WHERE end_date >= TO_DATE('2023-04-27')), with_dims AS (SELECT s.*, b.credit_limit FROM cleaned s LEFT JOIN customers b ON s.customer_id = b.id), deduped AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY status ORDER BY start_date_month_end NULLS FIRST) AS latest_rank FROM with_dims) t WHERE latest_rank = 1), deduped_subscriptions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY start_date DESC NULLS FIRST, id) AS dedup_rank FROM deduped) t WHERE dedup_rank = 1), base AS (SELECT *, CASE WHEN status IN ('PAUSED', 'ACTIVE') THEN 'Group A' ELSE 'Other' END AS status_group FROM deduped_subscriptions WHERE start_date >= DATE '2023-07-19') SELECT dim.city, s.status, COUNT(*) AS num_rows, ROUND(SUM(s.end_date_day), 2) AS total_end_date_day, ROUND(SUM(s.monthly_fee), 2) AS total_monthly_fee FROM base s JOIN customers dim ON s.customer_id = dim.id GROUP BY dim.city, s.status ORDER BY status NULLS FIRST;
